using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Drawing;using System.Windows.Forms;using System.Threading;using System.Reflection;using Prometheus;
class TestTimeline:Timeline {public void Down(int x,int y,MouseButtons button){OnMouseDown(new MouseEventArgs(button,1,x,y,0));}public void Motion(int x,int y){OnMouseMove(new MouseEventArgs(MouseButtons.Left,0,x,y,0));}public void Up(int x,int y){OnMouseUp(new MouseEventArgs(MouseButtons.Left,1,x,y,0));}public new void Enter(DragEventArgs e){OnDragEnter(e);}public void Drop(DragEventArgs e){OnDragDrop(e);} }
class TestForm:MainForm {public bool Command(Keys key){var message=new Message();return ProcessCmdKey(ref message,key);} }
class UiTests021 {
 static List<string> checks=new List<string>();static void Check(bool condition,string message){if(!condition)throw new Exception("FAIL "+message);checks.Add(message);Console.WriteLine("PASS "+message);}
 static object Field(object o,string name){return typeof(MainForm).GetField(name,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(o);}
 static IEnumerable<Control> Children(Control c){foreach(Control child in c.Controls){yield return child;foreach(var nested in Children(child))yield return nested;}}
 [STAThread]static void Main(string[] args){Application.EnableVisualStyles();Tools.Root=Path.GetFullPath(args[0]);string root=Path.GetFullPath(args[1]);var p=Store.Load(Path.Combine(Tools.Root,"demo","Demostracion.prometheus.json"));
  using(var t=new TestTimeline{Project=Store.Copy(p),Width=900,Height=320}){var first=t.Project.Active.clips.First(c=>t.Project.Active.tracks.Find(x=>x.id==c.track_id).kind=="video");first.name=new string('W',100);using(var a=new Bitmap(t.Width,t.Height))using(var b=new Bitmap(t.Width,t.Height)){t.Scroll=0;t.DrawToBitmap(a,new Rectangle(0,0,t.Width,t.Height));t.Scroll=0.8;t.DrawToBitmap(b,new Rectangle(0,0,t.Width,t.Height));bool identical=true;for(int y=32;y<t.Height;y++)for(int x=0;x<t.HeaderWidth;x++)if(a.GetPixel(x,y)!=b.GetPixel(x,y))identical=false;Check(identical,"clip labels never paint over track headers while scrolling");b.Save(Path.Combine(root,"timeline-scroll021.png"));}
   t.Scroll=15;double sought=-1;t.Seek=time=>sought=time;t.Down(t.HeaderWidth+275,100,MouseButtons.Left);Check(sought==20&&t.Cursor==20,"cursor can seek empty areas beyond last media");
   var calls=new List<bool>();t.ToggleTrack=(id,locked)=>calls.Add(locked);t.Down(10,40,MouseButtons.Left);Check(calls.Count==0,"track name click only selects, never toggles state");t.Down(15,65,MouseButtons.Left);t.Down(90,65,MouseButtons.Left);Check(calls.SequenceEqual(new[]{false,true}),"mute and lock have independent bounded hit regions");
   t.Down(t.HeaderWidth,12,MouseButtons.Left);t.Motion(240,12);t.Up(240,12);Check(t.HeaderWidth==240,"track header divider resizes manually");t.CollapseHeader();Check(t.HeaderWidth==76,"collapse preserves minimum usable track controls");t.CollapseHeader();Check(t.HeaderWidth==240,"expand restores previous manual width");Check(t.TimeAt(t.HeaderWidth)==15,"time coordinates use current header width");
   t.Scroll=0;bool context=false;var second=t.Project.Active.clips.First(c=>c.track_id!=first.track_id);t.Selection=new List<string>{first.id,second.id};t.ClipContext=point=>context=true;int row=t.Tracks().FindIndex(x=>x.id==first.track_id);t.Down((int)t.X(0.5),32+row*55+12,MouseButtons.Right);Check(context&&t.Selection.Count==2,"right-click exposes context actions and preserves multi-selection");
   var editor=new Editor();editor.Reset(Store.Copy(p));t.Project=editor.Project;t.CanDropAsset=(id,track,time)=>{try{var candidate=Store.Copy(editor.Project);Media.Insert(candidate,id,track,time);Store.Validate(candidate);return true;}catch{return false;}};t.DropAsset=(id,track,time)=>{editor.Commit(candidate=>Media.Insert(candidate,id,track,time));t.Project=editor.Project;};var asset=p.assets.First(a=>a.streams.Any(s=>s.kind=="video"));var target=t.Tracks().First(x=>x.kind=="video"&&x.order==0);row=t.Tracks().FindIndex(x=>x.id==target.id);var data=new DataObject();data.SetData("Prometheus.AssetId",asset.id);var screen=t.PointToScreen(new Point((int)t.X(8),32+row*55+12));var drag=new DragEventArgs(data,0,screen.X,screen.Y,DragDropEffects.Copy,DragDropEffects.None);int count=editor.Project.Active.clips.Count;t.Enter(drag);Check(drag.Effect==DragDropEffects.Copy&&editor.Project.Active.clips.Count==count,"library drag previews valid insertion without mutation");t.Drop(drag);Check(editor.Project.Active.clips.Count==count+2&&editor.Project.Active.clips.Count(c=>c.timeline_start.Seconds==8)==2,"library drop commits video and linked audio together");
   screen=t.PointToScreen(new Point((int)t.X(0),32+row*55+12));var collision=new DragEventArgs(data,0,screen.X,screen.Y,DragDropEffects.Copy,DragDropEffects.None);t.Enter(collision);Check(collision.Effect==DragDropEffects.None,"drag rejects occupied destination before drop");
  }
  using(var canvas=new PreviewCanvas{Width=500,Height=300,Image=new Bitmap(640,360)}){canvas.Percent(100);Check(canvas.ImageBounds().Width==1920,"100 percent monitor zoom references sequence dimensions");canvas.Percent(400);Check(canvas.ImageBounds().Width==7680,"manual monitor zoom accepts 400 percent");canvas.Fit();var rect=canvas.ImageBounds();Check(rect.Width<=500.001&&rect.Height<=300.001,"fit monitor keeps complete image inside available panel");canvas.Image.Dispose();}
  using(var frame=Rendering.Frame(p,p.Active.Length+10,CancellationToken.None)){Check(frame.GetPixel(100,100).R==0&&frame.GetPixel(100,100).G==0&&frame.GetPixel(100,100).B==0,"preview beyond content is black without last-frame repeat");}
  var progress=new List<double>();Rendering.Export(p,Path.Combine(root,"progress021.mp4"),CancellationToken.None,value=>{lock(progress)progress.Add(value);});Check(progress.Count>=3&&progress.First()==0&&progress.Last()==100&&progress.Zip(progress.Skip(1),(a,b)=>b>=a).All(x=>x),"export reports monotonic real progress and completion");Check(progress.Any(x=>x>0&&x<100),"export progress has processed-time updates before completion");
  try{Media.Inspect(Path.Combine(root,"not-compatible.txt"),CancellationToken.None);throw new Exception("unsupported media accepted");}catch(Exception ex){Check(ex.Message.Contains("Perfil inicial"),"unsupported extension has explicit compatibility reason");}
  typeof(MainForm).Assembly.GetType("Prometheus.App").GetField("Capture",BindingFlags.Public|BindingFlags.Static).SetValue(null,true);
  using(var form=new TestForm()){form.Show();Application.DoEvents();form.LoadFixture(Path.Combine(Tools.Root,"demo","Demostracion.prometheus.json"));Application.DoEvents();var timeline=(Timeline)Field(form,"timeline");timeline.Focus();timeline.Cursor=20;form.Command(Keys.Right);Check(Math.Abs(timeline.Cursor-20-1.0/60)<0.000001,"keyboard right advances exactly one frame beyond media end");form.Command(Keys.Left);Check(Math.Abs(timeline.Cursor-20)<0.000001,"keyboard left moves exactly one frame");var percent=(NumericUpDown)Field(form,"previewPercent");percent.Focus();double previous=timeline.Cursor;form.Command(Keys.Right);Check(timeline.Cursor==previous,"arrow shortcuts do not seek while editing zoom field");var buttons=Children(form).OfType<Button>().ToList();Check(buttons.Count(b=>b.Text=="EXPORTAR")==1&&buttons.First(b=>b.Text=="EXPORTAR").Dock==DockStyle.Right,"large export action stays anchored on upper right");var import=buttons.First(b=>b.Text=="Importar medios");Check(import.Parent.Parent.Controls.OfType<ListBox>().Any(),"import button belongs to media panel");Check(!buttons.Any(b=>b.Text=="Vincular"||b.Text=="Separar"||b.Text=="+ Video"||b.Text=="+ Audio"),"context actions and track types removed from main toolbar");var slider=(TrackBar)Field(form,"previewSlider");Check(slider.Minimum==10&&slider.Maximum==200&&percent.Maximum==400,"slider and manual monitor ranges match approved limits");
   var library=(ListBox)Field(form,"library");var projectEditor=(Editor)Field(form,"editor");int beforeCount=projectEditor.Project.assets.Count;var files=new DataObject();files.SetData(DataFormats.FileDrop,new[]{Path.Combine(Tools.Root,"demo","voz.wav")});typeof(Control).GetMethod("OnDragDrop",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(library,new object[]{new DragEventArgs(files,0,0,0,DragDropEffects.Copy,DragDropEffects.Copy)});var wait=System.Diagnostics.Stopwatch.StartNew();while((bool)Field(form,"busy")&&wait.Elapsed.TotalSeconds<10){Application.DoEvents();Thread.Sleep(20);}Check(library.AllowDrop&&projectEditor.Project.assets.Count==beforeCount+1,"Windows file-drop imports into library through background inspection");
   var exportPanel=(Panel)Field(form,"exportPanel");var cancel=(Button)Field(form,"cancelExport");var token=new CancellationTokenSource();typeof(MainForm).GetField("mediaToken",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(form,token);typeof(MainForm).GetField("exportRunning",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(form,true);exportPanel.Visible=true;cancel.PerformClick();Check(token.IsCancellationRequested,"visible export cancel button cancels its operation");typeof(MainForm).GetField("exportRunning",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(form,false);cancel.PerformClick();Check(!exportPanel.Visible,"completed or cancelled export strip can be hidden");
   timeline.Cursor=0.5;typeof(MainForm).GetMethod("Seek",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(form,new object[]{0.5});var renderWait=System.Diagnostics.Stopwatch.StartNew();while(renderWait.Elapsed.TotalSeconds<1.5){Application.DoEvents();Thread.Sleep(20);}((ExportProgressBar)Field(form,"exportProgress")).Value=42;((Label)Field(form,"exportLabel")).Text="Exportando · 42 %";exportPanel.Visible=true;using(var image=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(image,new Rectangle(0,0,image.Width,image.Height));image.Save(Path.Combine(root,"export-progress021.png"));}exportPanel.Visible=false;
   typeof(MainForm).GetField("dirty",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(form,false);form.Close();Application.DoEvents();}
  File.WriteAllText(Path.Combine(root,"checks-ui021.json"),Store.Json().Serialize(new{status="PASS",checks=checks,scope="Simulated WinForms events, draw clipping, progress and command handling; not manual desktop interaction"}));
 }
}


